cd "$ARCHON_HORIZON_ROOT" && "$HORIZON_GIT" log --oneline -1 && cd MainProjects/Algebraic-Jacobian-Challenge-Rebuild && python3 - <<'PY'
import os,re,collections
mods={}
for dp,_,fns in os.walk('AlgebraicJacobian'):
    for fn in fns:
        if fn.endswith('.lean'): mods[os.path.join(dp,fn)[:-5].replace('/','.')]=os.path.join(dp,fn)
mods['AlgebraicJacobian']='AlgebraicJacobian.lean'
imp=collections.defaultdict(set); dangling=set()
for m,p in mods.items():
    for line in open(p,encoding='utf-8',errors='replace'):
        mm=re.match(r'^import\s+(AlgebraicJacobian[\w.]*)',line)
        if mm:
            imp[m].add(mm.group(1))
            if mm.group(1) not in mods: dangling.add((m,mm.group(1)))
seen=set(); st=['AlgebraicJacobian']
while st:
    x=st.pop()
    if x in seen: continue
    seen.add(x); st.extend(d for d in imp[x] if d not in seen)
un=sorted(set(mods)-seen)
print(f"TOTAL={len(mods)}  ROOTED={len(seen&set(mods))}  UNROOTED={len(un)}  DANGLING={len(dangling)}")
for u in un: print("  ", u.split('.')[-1])
PY

cd "$ARCHON_HORIZON_ROOT/.archon-horizon/roadmap/history" && for f in AJCR.w4-rep.datum.dat-d.ddr.divrep.framecover-aff.jsonl AJCR.w4-rep.datum.dat-d.ddr.divrep.fieldmono-aff.jsonl; do echo "##### $f"; python3 -c "
